// Parse request
const query = $input.item.json.query || {};
const action = query.action || 'get_dashboard';
const studentId = parseInt(query.studentId) || 999;
const topicId = parseInt(query.topicId);
const subjectId = parseInt(query.subjectId);
const confidenceRating = parseInt(query.confidenceRating);

return {
  json: {
    action,
    studentId,
    topicId: topicId || null,
    subjectId: subjectId || null,
    confidenceRating: confidenceRating || null,
    timestamp: new Date().toISOString()
  }
};

// Build dashboard response
const summary = $('Fetch Dashboard Summary').first().json;
const activity = $('Fetch Recent Activity').all().map(i => i.json);
const topics = $('Fetch Topics Overview').all().map(i => i.json);

return {
  json: {
    success: true,
    student: {
      id: summary.student_id,
      name: summary.student_name,
      xpPoints: summary.xp_points,
      currentLevel: summary.current_level,
      streakDays: summary.streak_days,
      totalLessonsCompleted: summary.total_lessons_completed,
      totalPracticeQuestions: summary.total_practice_questions
    },
    stats: {
      lessonsCompleted: summary.lessons_completed_count || 0,
      questionsAttempted: summary.unique_questions_attempted || 0,
      averageScore: parseFloat(summary.avg_score_percentage) || 0,
      topicsMastered: summary.topics_mastered || 0
    },
    recentActivity: activity.map(a => ({
      type: a.event_type,
      resourceType: a.resource_type,
      resourceId: a.resource_id,
      metadata: typeof a.metadata === 'string' ? JSON.parse(a.metadata) : a.metadata,
      timestamp: a.timestamp
    })),
    topics: topics.map(t => ({
      id: t.topic_id,
      name: t.topic_name,
      subject: t.subject_name,
      masteryLevel: t.mastery_level || 0,
      confidenceLevel: t.confidence_level || 0,
      masteryStatus: t.mastery_status || 'Needs Work',
      questionsAttempted: t.practice_questions_attempted || 0,
      questionsCorrect: t.practice_questions_correct || 0,
      averageMarks: parseFloat(t.average_marks_percentage) || 0,
      lessonsCompleted: t.lessons_completed || 0,
      estimatedHours: parseFloat(t.estimated_hours) || 0
    })),
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

// Build topic mastery response
const mastery = $('Fetch Topic Mastery Detail').first().json;
const confidenceHistory = $('Fetch Confidence History').all().map(i => i.json);
const attempts = $('Fetch Recent Attempts').all().map(i => i.json);

if (!mastery || !mastery.mastery_id) {
  return {
    json: {
      success: false,
      error: 'No mastery data found for this topic',
      topicId: $('Parse Request').item.json.topicId
    }
  };
}

return {
  json: {
    success: true,
    topic: {
      id: mastery.topic_id,
      name: mastery.topic_name,
      code: mastery.topic_code,
      specificationRef: mastery.specification_ref,
      difficultyLevel: mastery.difficulty_level,
      estimatedHours: parseFloat(mastery.estimated_hours),
      subject: mastery.subject_name,
      examBoard: mastery.exam_board
    },
    mastery: {
      level: mastery.mastery_level,
      confidenceLevel: mastery.confidence_level,
      questionsAttempted: mastery.practice_questions_attempted,
      questionsCorrect: mastery.practice_questions_correct,
      averageMarks: parseFloat(mastery.average_marks_percentage),
      lessonsCompleted: mastery.lessons_completed,
      totalLessons: mastery.total_lessons,
      timeSpentMinutes: mastery.time_spent_minutes,
      lastPracticedAt: mastery.last_practiced_at,
      streakDays: mastery.streak_days,
      needsReview: mastery.needs_review,
      targetGrade: mastery.target_grade,
      predictedGrade: mastery.predicted_grade
    },
    confidenceHistory: confidenceHistory.map(c => ({
      rating: c.confidence_rating,
      context: c.context,
      notes: c.notes,
      loggedAt: c.logged_at
    })),
    recentAttempts: attempts.map(a => ({
      attemptId: a.attempt_id,
      marksAwarded: a.marks_awarded,
      marksPossible: a.marks_possible,
      isCorrect: a.is_correct,
      percentage: Math.round((a.marks_awarded / a.marks_possible) * 100),
      questionText: a.question_text?.slice(0, 100) + '...',
      difficulty: a.difficulty,
      attemptedAt: a.attempted_at
    })),
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

// Build confidence update response
const result = $input.first().json;
const request = $('Parse Request').item.json;

return {
  json: {
    success: true,
    message: 'Confidence rating updated',
    topicId: request.topicId,
    confidenceRating: request.confidenceRating,
    masteryLevel: result.mastery_level || 0,
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

return {
  json: {
    success: false,
    error: 'Unknown action',
    validActions: ['get_dashboard', 'get_topic_mastery', 'update_confidence']
  }
};

